{# Purchase Bill: Purchase Invoice with the company letterhead on top and footer at the bottom of every page (same page setup as the Sales order format). #}
{% set has_lh = letter_head and not no_letterhead %}
{% set has_footer = footer and not no_letterhead %}
{% set page_top = 8 %}{# blank space above the letterhead (mm) #}
{% set page_bottom = 6 %}{# blank space below the footer (mm) #}
{% set content_inset = 4 %}{# extra left / right space; the content, letterhead and footer all use it, so their edges (and the green/red bars) line up (mm) #}
{% set gap = 4 %}{# PDF: space between the letterhead / footer and the content (mm) #}
{% set lh_height = 36 %}{# PDF: letterhead height (mm) #}
{% set footer_height = 12 %}{# PDF: footer height, page number line included (mm) #}
{% set pdf_top = (page_top + lh_height + gap) if has_lh else 10 + page_top %}
{% set pdf_bottom = (gap + footer_height + page_bottom) if has_footer else 14 + page_bottom %}
{% set print_top = (40 if has_lh else 8) + page_top %}
{# browser print: space kept free above the footer. The footer image has a white area above the
   green/red bar that covers the content, so this must be the full image height, not just the bar #}
{% set print_bottom = (20 if has_footer else 8) + page_bottom %}
<style>
    /* PDF page margins (read by Frappe; only this exact ".print-format" selector works) */
    .print-format {
        margin-top: {{ pdf_top }}mm;
        margin-bottom: {{ pdf_bottom }}mm;
        margin-left: 8mm;
        margin-right: 8mm;
    }
    /* ...but don't apply them as real CSS margins */
    @media print { .print-format { margin: 0 !important; padding: 0 !important; } }

    /* Browser print (Ctrl+P / Print button): letterhead fixed at the top and footer fixed at the
       bottom of every page; the frame table's repeating thead / tfoot reserve that space.
       The PDF removes these .hidden-pdf spacers and uses the PDF margins above instead. */
    .si-frame { width: 100%; border-collapse: collapse; }
    .si-frame > tfoot { display: table-footer-group !important; }
    .print-format table.si-frame > * > tr > td { padding: 0 !important; }
    .si-frame td div.si { page-break-inside: auto !important; }
    .si-space-h, .si-space-f { display: none; }
    @media print {
        @page { size: A4; margin: 0 8mm; }
        .si-sheet > #header-html { position: fixed; top: 0; left: 0; right: 0; }
        .si-sheet > #footer-html { position: fixed; bottom: 0; left: 0; right: 0; }
        /* page margin above the letterhead / below the footer (PDF header & footer use these too) */
        #header-html { padding-top: {{ page_top }}mm; }
        #footer-html { padding-bottom: {{ page_bottom }}mm; }
        .si-space-h { display: block; height: {{ print_top }}mm; }
        .si-space-f { display: block; height: {{ print_bottom }}mm; }
    }
    @media screen {
        .print-format { margin: 0 auto !important; }
        /* browser preview: push the footer to the bottom of the A4 sheet */
        .si-sheet { display: flex; flex-direction: column; min-height: 10.1in; }
        .si-sheet > #footer-html { margin-top: auto !important; padding-top: 10px; }
    }

    /* PDF header / footer pages (Frappe renders them on their own, with <body onload="subst()">, and
       pulls .letter-head / .letter-head-footer up by 15mm). */
    body[onload] .letter-head { margin: {{ page_top - 15 }}mm 0 0 !important; }
    body[onload] .letter-head-footer { margin-top: {{ gap - 15 }}mm !important; }
    /* same left / right inset as the content (browser print and PDF), so the bars are as wide as the tables */
    .letter-head, .letter-head-footer, body[onload] .letter-head, body[onload] .letter-head-footer { padding: 0 {{ content_inset }}mm !important; box-sizing: border-box; }
    .letter-head img, .letter-head-footer img { width: 100% !important; max-width: 100% !important; height: auto !important; }
    .letter-head table, .letter-head-footer table { width: 100% !important; }
    /* browser print: the footer image's white area must not paint over the table above it
       (white becomes see-through, the green/red bar stays) */
    @media print {
        #footer-html, #footer-html * { background: transparent !important; }
        #footer-html img { mix-blend-mode: multiply; }
    }

</style>
<style>.pl-inset { padding: 0 {{ content_inset }}mm; }</style>
<div class="si-sheet">
<div id="header-html" class="hidden-pdf">
    {% if has_lh %}<div class="letter-head">{{ letter_head }}</div>{% endif %}
</div>
<table class="si-frame">
<thead class="hidden-pdf"><tr><td><div class="si-space-h"></div></td></tr></thead>
<tbody><tr><td><div class="pl-inset">
<style>
	.pb-title { margin: 1mm 0 3mm; font-size: 16px; text-align: center; color: #c0392b; font-weight: bold; }
	.pb-grid { width: 100%; border-collapse: collapse; font-size: 12px; margin-bottom: 8px; }
	.pb-grid td, .pb-grid th { border: 1px solid #000; padding: 5px 6px; vertical-align: top; }
	.pb-grid th { background: #eee; text-align: left; }
	.pb-num { text-align: right; white-space: nowrap; }
	.pb-info td:nth-child(odd) { width: 17%; font-weight: bold; }
	.pb-tot td { border: 1px solid #000; padding: 5px 8px; font-size: 13px; }
</style>
{% set sup = frappe.db.get_value("Supplier", doc.supplier, ["supplier_name", "tax_id"], as_dict=True) or {} %}
<div class="pb-title">PURCHASE INVOICE / فاتورة مشتريات{% if doc.docstatus == 0 %} &nbsp;(DRAFT){% endif %}</div>
<table class="pb-grid pb-info">
	<tr><td>Supplier</td><td>{{ sup.supplier_name or doc.supplier }}</td><td>Invoice No</td><td>{{ doc.name }}</td></tr>
	<tr><td>VAT No</td><td>{{ sup.tax_id or "" }}</td><td>Date</td><td>{{ frappe.format(doc.posting_date, {"fieldtype": "Date"}) }}</td></tr>
	<tr><td>Bill No</td><td>{{ doc.bill_no or "" }}</td><td>Ref</td><td>{{ doc.custom_daily_purchase_sheet or "" }}</td></tr>
</table>
<table class="pb-grid">
	<thead><tr><th style="width:5%">#</th><th>Item</th><th style="width:8%">Unit</th><th class="pb-num" style="width:10%">Qty</th><th class="pb-num" style="width:13%">Rate</th><th class="pb-num" style="width:16%">Amount</th></tr></thead>
	<tbody>
	{% for d in doc.items %}
		<tr><td>{{ loop.index }}</td><td>{{ d.item_name }} <span style="font-size:10px;color:#555">({{ d.item_code }})</span></td><td>{{ d.uom }}</td>
		<td class="pb-num">{{ "%g" | format(d.qty) }}</td><td class="pb-num">{{ "%.2f" | format(d.rate) }}</td><td class="pb-num">{{ "%.2f" | format(d.net_amount) }}</td></tr>
	{% endfor %}
	</tbody>
</table>
<table class="pb-tot" style="width:46%; margin-left:auto; border-collapse:collapse;">
	<tr><td>Total before VAT</td><td class="pb-num">{{ "%.2f" | format(doc.net_total) }}</td></tr>
	<tr><td>VAT</td><td class="pb-num">{{ "%.2f" | format(doc.total_taxes_and_charges) }}</td></tr>
	<tr><td><b>Total</b></td><td class="pb-num"><b>{{ "%.2f" | format(doc.grand_total) }}</b></td></tr>
</table>

</div></td></tr></tbody>
<tfoot class="hidden-pdf"><tr><td><div class="si-space-f"></div></td></tr></tfoot>
</table>
<div id="footer-html" class="visible-pdf">
    <div class="letter-head-footer">
        <div class="visible-pdf" style="text-align:center; font-size:8px; color:#000000; font-family:'DejaVu Sans', Arial, sans-serif; padding-bottom:2px;">
            {{ doc.name }} &nbsp;|&nbsp; Page <span class="page"></span> of <span class="topage"></span>
        </div>
        {% if has_footer %}{{ footer }}{% endif %}
    </div>
</div>
</div>
